tasks.codeTemplate:
level = 5
if level >= 5:
    print("🎉 You are ready for the quest!")

has_key = True
if has_key:
    print("🔑 The door opens!")

spell = "Fireball"
if spell == "Fireball":
    print("🔥 You cast a Fireball!")

roll = 18
if roll >= 15:
    print("⚔️ Critical hit!")
else:
    print("💨 Normal strike")

age = 17
if age >= 18:
    print("🍺 You may enter.")
else:
    print("🚫 Too young for this tavern.")

gold = 45
cost = 50
if gold >= cost:
    print(f"💰 Purchase successful! Remaining: {gold - cost}")
else:
    print(f"❌ Not enough gold! Missing: {cost - gold}")

xp = 750
if xp >= 1000:
    print("🏆 Master!")
elif xp >= 500:
    print("⭐ Advanced!")
elif xp >= 100:
    print("🌟 Beginner!")
else:
    print("📚 Still much to learn...")

element = "Water"
if element == "Fire":
    print("🔥 Fire Strike!")
elif element == "Water":
    print("💧 Water Torrent!")
elif element == "Air":
    print("🌪️ Wind Gust!")
elif element == "Earth":
    print("🗿 Earthquake!")
else:
    print("❓ Unknown element!")

has_key = True
has_torch = True
if has_key and has_torch:
    print("🗝️🔥 You can safely open the dark chamber!")

has_sword = False
has_wand = True
if has_sword or has_wand:
    print("⚔️ You are armed and ready!")

is_cursed = False
if not is_cursed:
    print("✨ You are free of any curse!")

strength = 8
intelligence = 12
if strength > 10 and intelligence > 10:
    print("⚔️🧠 Paladin!")
elif strength > 10:
    print("💪 Warrior!")
elif intelligence > 10:
    print("🧙 Mage!")
else:
    print("👤 Adventurer!")

door_locked = True
right_key = True

if door_locked:
    print("🚪 The door is locked.")
    if right_key:
        print("🔑 The key fits - the door opens!")
    else:
        print("❌ This key does not fit.")
else:
    print("🚪 The door is already open.")

age = 25
if age >= 18:
    print("Adult")
elif:
    print("Child")
